    var cells = {};
    picks.forEach(function (p) {
      var v = p.verdict || 'NONE', s = sportGroup(p.sport_key, p.sport_label);
      var k = v + '|' + s;
      cells[k] = cells[k] || { verdict: v, sport: s, rows: [] };
      cells[k].rows.push(p);
    });
