    if (typeof v === 'number') { out[String(r2(v))] = 1; out[String(Math.round(v))] = 1; if (Math.abs(v) <= 1) { out[String(Math.round(v * 100))] = 1; out[String(r2(v * 100))] = 1; } return out; }
